package com.calebzone.gateway.config;

import lombok.extern.slf4j.Slf4j;
import org.springframework.cloud.gateway.route.RouteLocator;
import org.springframework.cloud.gateway.route.builder.RouteLocatorBuilder;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpMethod;

/**
 * Gateway Routes Configuration
 * Defines all routes to downstream microservices
 */
@Slf4j
@Configuration
public class GatewayRoutesConfig {

    @Bean
    public RouteLocator customRouteLocator(RouteLocatorBuilder builder) {
        return builder.routes()
            // Auth Service Routes - Public and Protected
            .route("auth-service-public", r -> r
                .path("/auth/api/login", "/auth/api/register", "/auth/api/users/login", "/auth/api/users", "/auth/api/profiles/**")
                .and()
                .method(HttpMethod.POST, HttpMethod.GET)
                .filters(f -> f
                    .addRequestHeader("X-Gateway-Request", "true")
                    .addResponseHeader("X-Gateway-Response", "true")
                    .retry(config -> config.setRetries(2))
                )
                .uri("http://localhost:8081")
            )
            .route("auth-service-protected", r -> r
                .path("/auth/api/**")
                .filters(f -> f
                    .addRequestHeader("X-Gateway-Request", "true")
                    .addResponseHeader("X-Gateway-Response", "true")
                    .retry(config -> config.setRetries(2))
                    .circuitBreaker(config -> config
                        .setName("auth-service-cb")
                        .setFallbackUri("forward:/fallback/auth-service"))
                )
                .uri("http://localhost:8081")
            )

            // Air Service Routes
            .route("air-service", r -> r
                .path("/air/api/**")
                .filters(f -> f
                    .stripPrefix(0)
                    .addRequestHeader("X-Gateway-Request", "true")
                    .addResponseHeader("X-Gateway-Response", "true")
                    .retry(config -> config.setRetries(2))
                    .circuitBreaker(config -> config
                        .setName("air-service-cb")
                        .setFallbackUri("forward:/fallback/air-service"))
                )
                .uri("http://localhost:8082")
            )

            // AI Recognition Service Routes
            .route("ai-recognition-service", r -> r
                .path("/ai/api/**")
                .filters(f -> f
                    .stripPrefix(0)
                    .addRequestHeader("X-Gateway-Request", "true")
                    .addResponseHeader("X-Gateway-Response", "true")
                    .retry(config -> config.setRetries(2))
                    .circuitBreaker(config -> config
                        .setName("ai-service-cb")
                        .setFallbackUri("forward:/fallback/ai-service"))
                )
                .uri("http://localhost:8083")
            )

            // Gateway own endpoints
            .route("gateway-health", r -> r
                .path("/gateway/**")
                .filters(f -> f
                    .addRequestHeader("X-Gateway-Request", "true")
                )
                .uri("forward:/gateway")
            )

            // Fallback route for undefined paths
            .route("fallback-route", r -> r
                .path("/**")
                .filters(f -> f
                    .setStatus(404)
                )
                .uri("no://op")
            )
            .build();
    }
}

package com.calebzone.gateway.config;

import com.calebzone.gateway.security.JwtAuthenticationConverter;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.reactive.EnableWebFluxSecurity;
import org.springframework.security.config.web.server.ServerHttpSecurity;
import org.springframework.security.oauth2.jwt.NimbusReactiveJwtDecoder;
import org.springframework.security.oauth2.jwt.ReactiveJwtDecoder;
import org.springframework.security.web.server.SecurityWebFilterChain;

import javax.crypto.SecretKey;
import javax.crypto.spec.SecretKeySpec;
import java.util.Base64;

@Slf4j
@Configuration
@EnableWebFluxSecurity
@RequiredArgsConstructor
public class SecurityConfig {

    private final JwtAuthenticationConverter jwtAuthenticationConverter;

    @Value("${application.security.authentication.jwt.base64-secret}")
    private String jwtSecret;

    @Bean
    public SecurityWebFilterChain springSecurityFilterChain(ServerHttpSecurity http) {
        http
            .csrf(ServerHttpSecurity.CsrfSpec::disable)
            .authorizeExchange(exchange -> exchange
                // Public endpoints - no authentication required
                .pathMatchers("/auth/api/login", "/auth/api/register", "/auth/api/users/login").permitAll()
                .pathMatchers("/auth/api/users", "/auth/api/profiles/**").permitAll()
                .pathMatchers("/gateway/health", "/gateway/info").permitAll()
                .pathMatchers("/actuator/**").permitAll()
                .pathMatchers("/swagger-ui/**", "/v3/api-docs/**", "/swagger-ui.html").permitAll()
                .pathMatchers("/webjars/**", "/favicon.ico").permitAll()
                // All other requests require authentication
                .anyExchange().authenticated()
            )
            .oauth2ResourceServer(oauth2 -> oauth2
                .jwt(jwt -> jwt
                    .jwtDecoder(jwtDecoder())
                    .jwtAuthenticationConverter(jwtAuthenticationConverter::convert)
                )
            );

        return http.build();
    }

    @Bean
    public ReactiveJwtDecoder jwtDecoder() {
        try {
            // Decode the Base64 secret key
            byte[] keyBytes = Base64.getDecoder().decode(jwtSecret);
            SecretKey key = new SecretKeySpec(keyBytes, "HmacSHA512");

            return NimbusReactiveJwtDecoder.withSecretKey(key).build();
        } catch (Exception e) {
            log.error("Error creating JWT decoder", e);
            throw new RuntimeException("Failed to create JWT decoder", e);
        }
    }
}

package com.calebzone.gateway.filter.factory;

import lombok.extern.slf4j.Slf4j;
import org.springframework.cloud.gateway.filter.GatewayFilterChain;
import org.springframework.cloud.gateway.filter.GlobalFilter;
import org.springframework.core.Ordered;
import org.springframework.http.HttpHeaders;
import org.springframework.http.server.reactive.ServerHttpRequest;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.ReactiveSecurityContextHolder;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.stereotype.Component;
import org.springframework.web.server.ServerWebExchange;
import reactor.core.publisher.Mono;

/**
 * Filter to forward JWT token and user information to downstream services
 */
@Slf4j
@Component
public class AuthenticationFilter implements GlobalFilter, Ordered {

    @Override
    public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
        return ReactiveSecurityContextHolder.getContext()
            .flatMap(securityContext -> {
                Authentication authentication = securityContext.getAuthentication();

                if (authentication != null && authentication.isAuthenticated()
                    && authentication.getPrincipal() instanceof Jwt jwt) {

                    // Extract user information from JWT
                    String username = jwt.getClaimAsString("sub"); // Subject is typically the username
                    String userId = jwt.getClaimAsString("userId");
                    String email = jwt.getClaimAsString("email");

                    // Add headers for downstream services
                    ServerHttpRequest.Builder requestBuilder = exchange.getRequest().mutate()
                        .header("X-Auth-User", username != null ? username : "")
                        .header("X-Auth-Token", exchange.getRequest().getHeaders().getFirst(HttpHeaders.AUTHORIZATION));

                    if (userId != null) {
                        requestBuilder.header("X-Auth-User-Id", userId);
                    }
                    if (email != null) {
                        requestBuilder.header("X-Auth-Email", email);
                    }

                    log.debug("Forwarding request for user: {}, userId: {}", username, userId);

                    return chain.filter(exchange.mutate().request(requestBuilder.build()).build());
                }

                return chain.filter(exchange);
            })
            .onErrorResume(error -> {
                log.debug("No security context available, proceeding without authentication headers");
                return chain.filter(exchange);
            });
    }

    @Override
    public int getOrder() {
        return 0;
    }
}

package com.calebzone.air.application.search.service;

import com.calebzone.air.application.search.port.in.SearchFlightsUseCase;
import com.calebzone.air.application.search.port.out.FlightCachePort;
import com.calebzone.air.application.search.port.out.FlightSupplierPort;
import com.calebzone.air.domain.search.FlightSearchResults;
import com.calebzone.air.domain.search.SearchCriteria;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

import java.util.Optional;

/**
 * Application Service: Orchestrates the flight search use case.
 * Coordinates between port-out interfaces (cache, supplier) without containing business logic.
 */
@Slf4j
@Service
@RequiredArgsConstructor
public class SearchFlightsService implements SearchFlightsUseCase {
    private final FlightSupplierPort supplierPort;
    private final FlightCachePort cachePort;

    @Override
    public FlightSearchResults search(SearchCriteria criteria) {
        // 1. Check cache first
        Optional<FlightSearchResults> cachedResults = cachePort.getCachedResults(criteria);
        if (cachedResults.isPresent()) {
            log.info("Found results in cache for criteria: {}", criteria);
            return cachedResults.get();
        }

        // 2. Call external supplier via port-out
        FlightSearchResults results = supplierPort.searchExternalFlights(criteria);

        // 3. Cache the results
        if (results != null && results.getItineraries() != null && !results.getItineraries().isEmpty()) {
            log.info("Caching {} results from supplier", results.getItineraries().size());
            cachePort.cacheResults(criteria, results);
        }

        return results;
    }
}

package com.calebzone.core.exception;

import com.calebzone.core.exception.error.BaseErrorCode;
import com.calebzone.core.exception.error.ErrorCode;
import com.calebzone.core.exception.error.ErrorDetail;
import jakarta.validation.ConstraintViolationException;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.apache.coyote.BadRequestException;
import org.jspecify.annotations.Nullable;
import org.slf4j.MDC;
import org.springframework.context.MessageSource;
import org.springframework.context.i18n.LocaleContextHolder;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatusCode;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.BindingResult;
import org.springframework.validation.FieldError;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.context.request.WebRequest;
import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;

import java.util.List;
import java.util.UUID;

@Slf4j
@RestControllerAdvice
@RequiredArgsConstructor
//@Order(Ordered.HIGHEST_PRECEDENCE)
public class GlobalExceptionHandler extends ResponseEntityExceptionHandler {
    public static final String TRACE_ID_PARAM = "traceId";
    public static final String ERROR_PARAM = "error";
    public static final String FIELD_ERROR_PARAM = "fieldErrors";
    private final MessageSource messageSource;

    protected String resolveMessage(String code, String defaultMessage, Object... args) {
        return messageSource.getMessage(code, args, defaultMessage, LocaleContextHolder.getLocale());
    }

    @Override
    protected ResponseEntity<Object> handleMethodArgumentNotValid(MethodArgumentNotValidException ex,
                                                                  HttpHeaders headers,
                                                                  HttpStatusCode status,
                                                                  WebRequest request) {
        ProblemDetail problemDetail = ProblemDetail.forStatus(status);

        problemDetail.setProperty(ERROR_PARAM, this.toErrorDetail(ErrorCode.REQUEST_VALIDATION_ERROR));
        problemDetail.setProperty(FIELD_ERROR_PARAM, this.buildValidationErrors(ex.getBindingResult()));

        return this.handleExceptionInternal(ex, problemDetail, headers, status, request);
    }

    private ErrorDetail toErrorDetail(BaseErrorCode errorCode, Object... args) {
        return ErrorDetail.builder()
            .code(errorCode.getCode())
            .category(errorCode.getCategory().name())
            .message(this.resolveMessage(errorCode.getCode(), null, args))
            .build();
    }

    protected List<ErrorDetail> buildValidationErrors(BindingResult bindingResult) {
        return bindingResult.getAllErrors().stream()
            .map(objectError -> ErrorDetail.builder()
                .field(objectError instanceof FieldError fieldError ? fieldError.getField() : objectError.getObjectName())
                .code(objectError.getCode())
                .message(this.resolveMessage(objectError.getCode(), null, objectError.getArguments()))
                .build())
            .toList();
    }

    @Override
    protected @Nullable ResponseEntity<Object> handleExceptionInternal(Exception ex, @Nullable Object body, HttpHeaders headers, HttpStatusCode statusCode, WebRequest request) {
        if (statusCode.is5xxServerError()) {
            log.error("System Exception ({}): ", statusCode.value(), ex);
        } else if (log.isDebugEnabled()) {
            log.debug("Client Error ({}): {}", statusCode.value(), ex.getMessage());
        }
        return super.handleExceptionInternal(ex, body, headers, statusCode, request);
    }

    @ExceptionHandler(BaseException.class)
    public ResponseEntity<Object> handleBaseException(BaseException ex, WebRequest request) {
        BaseErrorCode errorCode = ex.getErrorCode();

        ProblemDetail body = ProblemDetail.forStatus(errorCode.getHttpStatus());
        body.setProperty(ERROR_PARAM, this.toErrorDetail(errorCode, ex.getArgs()));

        return this.handleExceptionInternal(ex, body, new HttpHeaders(), errorCode.getHttpStatus(), request);
    }

    @Override
    protected ResponseEntity<Object> createResponseEntity(@Nullable Object body, HttpHeaders headers, HttpStatusCode statusCode, WebRequest request) {
        if (body instanceof ProblemDetail problemDetail) {
            problemDetail.setType(null);
            problemDetail.setTitle(null);
            problemDetail.setProperty(TRACE_ID_PARAM, this.currentTraceId());
        }
        return super.createResponseEntity(body, headers, statusCode, request);
    }

    private String currentTraceId() {
        String traceId = MDC.get("traceId");
        return traceId != null ? traceId : UUID.randomUUID().toString();
    }
}
